function docsV(){return`<label class="dz"><input type="file" id="up" accept=".pdf,.xlsx,.xls,.csv" multiple hidden><div class="dzi">📥</div><b>גרור לכאן קבצי PDF או Excel</b><div class="src">או לחץ לבחירה · העיבוד מתבצע במכשיר בלבד ואינו נשלח לשום שרת</div></label><div class="warn">נשמר התוכן המחולץ והמקורות (לא קובץ המקור). מסמכים שהועלו בגרסה קודמת חסרים את נתוני השורה המלאים – העלה אותם שוב. PDF סרוק ללא טקסט יסומן (OCR לא כלול).</div><div class="grid">${S.docs.map(d=>`<div class="card"><b>${esc(d.name)}</b> <span class="tag">גרסה ${d.ver}</span><div class="src">${esc(d.date)} · ${d.type==='pdf'?'עמודים':'גיליונות'}: ${d.pages??'-'} · סעיפים: ${d.count??'-'}</div><div class="src">מצב: ${esc(d.status)}${d.dict?` · נוספו ${d.dict} מונחים למילון`:''}</div><button class="b r" data-a="deld" data-i="${d.id}">מחק מסמך</button></div>`).join('')}</div>`}
function commV(){return`${INTRO_C()}<div class="card"><button class="b" data-a="fnewf">+ ממצא חדש</button><button class="b g" data-a="fxlf">Excel</button><button class="b g" data-a="fprf">הדפסה</button><div class="warn">עצם קיום דרישה במפרט אינו מוכיח עבודה נוספת בתשלום. הממצאים הם נקודות לבירור – לא מסקנות משפטיות.</div></div><div class="grid">${S.finds.map((f,k)=>`<div class="card"><select data-a="fe" data-f="type" data-i="${k}">${FT.map(t=>`<option${t===f.type?' selected':''}>${t}</option>`).join('')}</select>${[['title','תיאור הממצא'],['source','מקור מדויק'],['why','למה זה חשוב'],['check','מה לבדוק'],['doc','מה לתעד'],['action','המלצה לפעולה'],['draft','טיוטת פנייה לבינוי/פיקוח']].map(([a,l])=>`<label class="src">${l}</label><textarea data-a="fe" data-f="${a}" data-i="${k}">${esc(f[a]||'')}</textarea>`).join('')}<div class="noprint"><button class="b g" data-a="fdr" data-i="${k}">העתק טיוטה</button><button class="b r" data-a="fdelf" data-i="${k}">מחק</button></div></div>`).join('')}</div>`}
function setV(){return aiV()+`<div class="card"><b>מונחים נפוצים בכתב הכמויות</b> <span class="src">(לחיצה = חיפוש)</span><div class="chips">${Core.topTerms(ITEMS.filter(i=>i.kind==='boq'),40).map(t=>`<button class="chip" data-a="chip" data-i="${esc(t)}">${esc(t)}</button>`).join('')||'<span class="src">אין עדיין נתונים</span>'}</div></div><div class="card"><b>מילון אוטומטי</b><div class="src">המילון מתעדכן אחרי כל העלאה: צורות כתיב/ריבוי וצמדי מונחים שכתובים יחד ("X / Y", "X (Y)"). מילים נרדפות שלא כתובות יחד – יש להוסיף ידנית.</div><button class="b" data-a="auto">⚙️ בנה/עדכן עכשיו</button></div><div class="card"><b>מילון מונחים (שורה לכל קבוצה, מופרד בפסיקים)</b><textarea id="syn" style="min-height:220px">${esc(S.syn.map(g=>g.join(', ')).join('\n'))}</textarea><button class="b" data-a="syns">שמור מילון</button><button class="b g" data-a="synr">שחזר ברירת מחדל</button></div><div class="card"><b>גיבוי ושחזור</b><div class="warn">הנתונים נשמרים במכשיר זה בלבד – אין סנכרון ואין גיבוי בענן. הורד גיבוי באופן קבוע.</div><button class="b" data-a="bk">הורד גיבוי</button><input type="file" id="rf" accept=".json"></div><div class="card src">כל התלויות (SheetJS, PDF.js) קוד פתוח, פועלות מקומית ובחינם. לא נשלח מידע לשום שירות, ללא API וללא מפתחות.</div>`}
