let paint=null,lastP=null,raf=0;
function loop(){if(paint===null||!lastP){raf=0;return}const H=innerHeight,tz=130,bar=document.querySelector('#bar'),obs=(bar&&bar.style.display!=='none'?bar.offsetHeight:0)+(innerWidth<=700?50:0),bz=obs+70,y=lastP.y;let sp=0;if(y<tz)sp=-Math.min(24,(tz-y)/tz*26+2);else if(y>H-bz)sp=Math.min(24,(y-(H-bz))/bz*26+2);if(sp)scrollBy(0,sp);const el=document.elementFromPoint(lastP.x,Math.min(Math.max(y,60),H-obs-8)),c=el&&el.closest('[data-id]');if(c)setSel(c.dataset.id,paint);raf=requestAnimationFrame(loop)}
document.addEventListener('pointerdown',e=>{const s=e.target.closest('.selbox')||(SELMODE&&!e.target.closest('button,a,input,select,textarea,label')&&e.target.closest('[data-id]'));if(!s)return;const id=s.dataset.sid||s.dataset.id;paint=!SEL.has(id);setSel(id,paint);lastP={x:e.clientX,y:e.clientY};if(!raf)raf=requestAnimationFrame(loop);e.preventDefault()});
