function addGroups(gs){for(const g of gs){const ng=g.map(Core.norm),t=S.syn.find(o=>o.map(Core.norm).some(p=>ng.includes(p)));if(!t){S.syn.push(g);continue}const have=t.map(Core.norm);g.forEach(p=>{if(!have.includes(Core.norm(p)))t.push(p)})}}

