const PDFC=new Map(),OFFB=new Set(),OFFP=new Set();let PGREC=new Map();
const getPdf=id=>{if(!PDFC.has(id))PDFC.set(id,(async()=>{const f=await getFile(id);if(!f)return null;pdfjsLib.GlobalWorkerOptions.workerSrc='lib/pdf.worker.min.js';return pdfjsLib.getDocument({data:new Uint8Array(f.buf.slice(0))}).promise})());return PDFC.get(id)};
function origGroups(L){const g=new Map(),pg=new Map();for(const r of L){const it=r.it;if(it.kind==='boq'){const k=it.docId+'|'+it.sheet;if(!g.has(k))g.set(k,[]);g.get(k).push(r)}else if(it.page){const k=it.docId+'|'+it.page;if(!pg.has(k))pg.set(k,{docId:it.docId,page:it.page,rs:[]});pg.get(k).rs.push(r)}}
const gs=[...g.values()].map(x=>x.sort((p,q)=>p.it.row-q.it.row)),ps=[...pg.values()].sort((x,y)=>(S.docs.findIndex(d=>d.id===x.docId)-S.docs.findIndex(d=>d.id===y.docId))||x.page-y.page);return{gs,ps}}
function origV(L){const{gs,ps}=origGroups(L);PGREC=new Map(ps.map(p=>[p.docId+'|'+p.page,p]));const nb=gs.reduce((s,x)=>s+x.length,0);
let h=`<div class="chips noprint">${nb?`<button class="chip" data-a="goto" data-i="sec-boq">📊 כתב כמויות: ${nb} שורות ⬇</button>`:''}${ps.length?`<button class="chip" data-a="goto" data-i="sec-spec">📑 מפרט: ${ps.length} עמודים ⬇</button>`:''}<span class="src">הכול מסומן לייצוא – הסר סימון ממה שלא רוצים. בסוף הדף כפתור ייצוא.</span></div>`;
if(nb){h+='<div id="sec-boq"></div>';for(const rs of gs){const f=rs[0].it,doc=S.docs.find(d=>d.id===f.docId)||{},sh=doc.sh&&doc.sh[f.sheet],hdr=sh?sh.hdr:(f.fields||[]).map(x=>x[0]);
h+=`<div class="xlw"><div class="xlt">📊 ${esc(doc.name||f.docName)} · גיליון ${esc(f.sheet)} · ${rs.length} שורות <label class="chk noprint"><input type="checkbox" data-a="offall" data-i="${esc(f.docId+'|'+f.sheet)}" checked> הכול</label></div><div class="tw"><table class="xl"><thead><tr><th class="rn">שורה</th>${hdr.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>{const it=r.it,cells=it.cells||(it.fields||[]).map(x=>x[1]);return`<tr class="mk${OFFB.has(it.id)?' off':''}" data-nav="1" data-bid="${it.id}"><td class="rn"><input type="checkbox" data-a="offb" data-i="${it.id}"${OFFB.has(it.id)?'':' checked'}> ${it.row}</td>${cells.map(v=>`<td>${String(v)===String(it.text)?hlt(it.text,r.hits):esc(v)}</td>`).join('')}</tr>`}).join('')}</tbody></table></div></div>`}}
if(ps.length){h+='<div id="sec-spec"></div>';ps.forEach(p=>{const doc=S.docs.find(d=>d.id===p.docId)||{},k=p.docId+'|'+p.page;h+=`<div class="pgc${OFFP.has(k)?' off':''}" data-nav="1" data-pk="${esc(k)}"><div class="xlt"><label class="chk"><input type="checkbox" data-a="offp" data-i="${esc(k)}"${OFFP.has(k)?'':' checked'}> 📑 ${esc(doc.name||'')} · עמוד ${p.page}</label> <span class="src">סעיפים: ${esc(p.rs.map(r=>r.it.ref).filter(Boolean).join(', ')||'—')}</span></div>${doc.file?`<canvas class="pgcv" data-pk="${esc(k)}"></canvas>`:`<div class="warn">המסמך הועלה בגרסה ישנה ולכן אין לו עמוד מקורי. העלה אותו שוב כדי לראות את העמוד כמו במקור. הטקסט שחולץ:<div class="txt">${p.rs.map(r=>hlt(r.it.text,r.hits)).join('<hr>')}</div></div>`}</div>`})}
return h}
let IO=null;
async function drawPage(cv,key,docId,page,items,mark){const pdf=await getPdf(docId);if(!pdf)return;const pg=await pdf.getPage(page),w=cv.parentElement.clientWidth||700,v1=pg.getViewport({scale:1}),vp=pg.getViewport({scale:Math.min(3,(w/v1.width)*Math.min(2,devicePixelRatio||1))});cv.width=vp.width;cv.height=vp.height;cv.style.width='100%';const ctx=cv.getContext('2d');await pg.render({canvasContext:ctx,viewport:vp}).promise;
if(mark){ctx.globalCompositeOperation='multiply';ctx.fillStyle='rgba(255,226,0,.6)';for(const it of items)for(const r of (it.rects||[]).filter(z=>z.p===page)){const q=vp.convertToViewportRectangle([r.x1,r.y1,r.x2,r.y2]);ctx.fillRect(Math.min(q[0],q[2]),Math.min(q[1],q[3]),Math.abs(q[2]-q[0]),Math.abs(q[3]-q[1]))}}}
function afterList(){if(IO)IO.disconnect();const cvs=document.querySelectorAll('canvas.pgcv');if(cvs.length){IO=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const cv=e.target;IO.unobserve(cv);const p=PGREC.get(cv.dataset.pk);if(p)drawPage(cv,cv.dataset.pk,p.docId,p.page,p.rs.map(r=>r.it),P().hl).catch(x=>{cv.replaceWith(Object.assign(document.createElement('div'),{className:'warn',textContent:'שגיאה בהצגת העמוד: '+x.message}))})}),{rootMargin:'600px'});cvs.forEach(c=>IO.observe(c))}
let x=$('#xbar');if(!x){x=document.createElement('div');x.id='xbar';x.className='noprint';document.body.appendChild(x)}const on=tab==='home'&&P().vm==='orig'&&res.length,s=origSel();x.style.display=on?'flex':'none';document.body.classList.toggle('hasx',!!on);if(on)x.innerHTML=`<b>${s.boq.length} שורות · ${s.pages.length} עמודי מפרט</b><button class="b" data-a="xexp">⬇ ייצוא / הדפסה / שליחה</button>`;
const f2=$('#fab2');if(f2)f2.hidden=!document.querySelector('[data-nav]')}
function origSel(){if(!(tab==='home'&&P().vm==='orig'))return{boq:[],pages:[]};const{gs,ps}=origGroups(vres());return{boq:gs.flat().map(r=>r.it).filter(i=>!OFFB.has(i.id)),pages:ps.filter(p=>!OFFP.has(p.docId+'|'+p.page)).map(p=>({docId:p.docId,page:p.page,items:p.rs.map(r=>r.it)}))}}
const loadScript=src=>new Promise((ok,no)=>{if(document.querySelector(`script[data-l="${src}"]`))return ok();const s=document.createElement('script');s.src=src;s.dataset.l=src;s.onload=ok;s.onerror=()=>no(Error('נכשלה טעינת '+src));document.head.appendChild(s)});
async function makeXlsx(items,mk){await loadScript('lib/exceljs.min.js');const out=[],by=new Map();items.forEach(i=>{if(!by.has(i.docId))by.set(i.docId,[]);by.get(i.docId).push(i)});
for(const[docId,L]of by){const f=await getFile(docId),doc=S.docs.find(d=>d.id===docId);if(!f){out.push({name:'חסר מקור.txt',blob:new Blob(['המסמך המקורי לא נשמר – העלה אותו שוב'])});continue}
const wb=new ExcelJS.Workbook();await wb.xlsx.load(f.buf.slice(0));const sheets=[...new Set(L.map(i=>i.sheet))];
for(const ws of [...wb.worksheets]){if(!sheets.includes(ws.name)){wb.removeWorksheet(ws.id);continue}
const keep=new Set(L.filter(i=>i.sheet===ws.name).map(i=>i.row)),sh=doc.sh&&doc.sh[ws.name],hdrRow=sh&&sh.hi>=0?sh.r0+sh.hi+1:0;
ws.eachRow(r=>r.eachCell(c=>{const v=c.value;if(v&&typeof v==='object'&&'formula' in v)c.value=v.result==null?'':v.result;else if(v&&typeof v==='object'&&'sharedFormula' in v)c.value=v.result==null?'':v.result}));
if(mk)keep.forEach(n=>ws.getRow(n).eachCell({includeEmpty:true},c=>{c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFFFF2A8'}}}));
for(let r=ws.rowCount;r>hdrRow;r--)if(!keep.has(r))ws.spliceRows(r,1)}
const buf=await wb.xlsx.writeBuffer();out.push({name:(doc.name||'boq').replace(/\.[^.]+$/,'')+'-נבחרים.xlsx',blob:new Blob([buf],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})})}return out}
async function makePdf(pages,mk){await loadScript('lib/pdf-lib.min.js');const{PDFDocument,rgb,BlendMode}=PDFLib,out=[],by=new Map();pages.forEach(p=>{if(!by.has(p.docId))by.set(p.docId,[]);by.get(p.docId).push(p)});
for(const[docId,L]of by){const f=await getFile(docId),doc=S.docs.find(d=>d.id===docId);if(!f)continue;const src=await PDFDocument.load(f.buf.slice(0)),dst=await PDFDocument.create(),ps=L.sort((x,y)=>x.page-y.page),cp=await dst.copyPages(src,ps.map(p=>p.page-1));
cp.forEach((pg,k)=>{dst.addPage(pg);if(mk)for(const it of ps[k].items)for(const r of (it.rects||[]).filter(z=>z.p===ps[k].page))pg.drawRectangle({x:r.x1,y:r.y1,width:r.x2-r.x1,height:r.y2-r.y1,color:rgb(1,.9,0),opacity:.5,blendMode:BlendMode.Multiply})});
out.push({name:(doc.name||'spec').replace(/\.[^.]+$/,'')+'-עמודים-נבחרים.pdf',blob:new Blob([await dst.save()],{type:'application/pdf'})})}return out}
const dl=(name,blob)=>{const l=document.createElement('a');l.href=URL.createObjectURL(blob);l.download=name;l.click()};
async function doExport(){const s=origSel();if(!s.boq.length&&!s.pages.length)return toast('לא נבחר כלום לייצוא');
const v=await modal(`<b>ייצוא: ${s.boq.length} שורות · ${s.pages.length} עמודי מפרט</b><div class="src">הקבצים נוצרים מהקבצים המקוריים שהעלית – אותו עיצוב, רק השורות/העמודים שנבחרו.</div>${[['f','קבצים: Excel מקורי + PDF מקורי (הורדה)'],['s','שיתוף קבצים (וואטסאפ / מייל וכו׳ – בטלפון)'],['pr','הדפסה'],['c','העתקת טקסט'],['m','טיוטת מייל (טקסט בלבד, קבצים מצרפים ידנית)']].map(([k,l],i)=>`<label class="chk"><input type="radio" name="xf" value="${k}"${i?'':' checked'}> ${l}</label>`).join('')}<label class="chk"><input type="checkbox" id="xmk" checked> סימון צהוב של השורות/הסעיפים</label>`,()=>({f:document.querySelector('[name=xf]:checked').value,mk:$('#xmk').checked}),'המשך');if(!v)return;
const txt=()=>[...s.boq.map(i=>`[כתב כמויות · ${i.docName} · גיליון ${i.sheet} · שורה ${i.row}] ${(i.cells||[]).filter(Boolean).join(' | ')}`),...s.pages.flatMap(p=>p.items.map(i=>`[מפרט · ${i.docName} · עמוד ${i.page} · סעיף ${i.ref||'-'}] ${i.text}`))].join('\n\n');
try{if(v.f==='c')return copy(txt());if(v.f==='m')return void(location.href='mailto:?subject='+encodeURIComponent('שורות וסעיפים רלוונטיים')+'&body='+encodeURIComponent(txt().slice(0,1800)));
if(v.f==='pr'){S.prefs.hl=v.mk;await save();return window.print()}
toast('מכין קבצים…',0);const fl=[...(s.boq.length?await makeXlsx(s.boq,v.mk):[]),...(s.pages.length?await makePdf(s.pages,v.mk):[])];$('#toast').style.display='none';
if(v.f==='s'){const files=fl.map(x=>new File([x.blob],x.name,{type:x.blob.type}));if(navigator.canShare&&navigator.canShare({files}))await navigator.share({files,title:'שורות וסעיפים רלוונטיים'});else{toast('השיתוף אינו נתמך בדפדפן הזה – הקבצים יורדו');fl.forEach(x=>dl(x.name,x.blob))}}else fl.forEach(x=>dl(x.name,x.blob))}catch(e){$('#toast').style.display='none';await modal(`<b>הייצוא נכשל</b><p>${esc(e.message)}</p>`,null,'הבנתי')}}
async function viewPage(id){const it=ITEMS.find(x=>x.id===id),doc=S.docs.find(d=>d.id===it.docId);if(!doc||!doc.file)return toast('אין עמוד מקורי – העלה את המפרט שוב');const d=D();d.style.width='min(900px,96vw)';d.innerHTML=`<b>${esc(it.docName)} · עמוד ${it.page}</b><div class="pgw" style="margin:8px 0"><canvas id="vpc"></canvas></div><div class="row mrow"><button class="b g" id="vpx">סגור</button></div>`;d.showModal();$('#vpx').onclick=()=>d.close();try{await drawPage($('#vpc'),'',it.docId,it.page,[it],true)}catch(e){toast('שגיאה: '+esc(e.message))}}
